function largestSumDivisibleByThree(nums: number[]): number {
  const n = nums.length;
  let best = 0;
  for (let mask = 0; mask < 1 << n; mask++) {
    let sum = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) sum += nums[i];
    if (sum % 3 === 0) best = Math.max(best, sum);
  }
  return best;
}

