function largestSumDivisibleByThree(nums: number[]): number {
  let total = 0;
  // two smallest numbers for remainders 1 and 2
  const small = [[], [Infinity, Infinity], [Infinity, Infinity]] as number[][];
  for (const x of nums) {
    total += x;
    const m = small[x % 3];
    if (x % 3 === 0) continue;
    if (x < m[0]) { m[1] = m[0]; m[0] = x; }
    else if (x < m[1]) m[1] = x;
  }
  const r = total % 3;
  if (r === 0) return total;
  const other = 3 - r;
  const cost = Math.min(small[r][0], small[other][0] + small[other][1]);
  return cost === Infinity ? 0 : total - cost;
}

