class Solution:
    def largestSumDivisibleByThree(self, nums: List[int]) -> int:
        total = sum(nums)
        r = total % 3
        if r == 0:
            return total
        by_rem = {1: sorted(x for x in nums if x % 3 == 1)[:2], 2: sorted(x for x in nums if x % 3 == 2)[:2]}
        options = []
        if by_rem[r]:
            options.append(by_rem[r][0])
        if len(by_rem[3 - r]) == 2:
            options.append(sum(by_rem[3 - r]))
        return total - min(options) if options else 0

