function largestSumDivisibleByThree(nums: number[]): number {
  let best = [0, -Infinity, -Infinity];
  for (const x of nums) {
    const old = best.slice();
    for (let r = 0; r < 3; r++) {
      const to = (r + x) % 3;
      best[to] = Math.max(best[to], old[r] + x);
    }
  }
  return best[0];
}

